"""
apply_day21.py -- Day 21 installer: optional real OpenTelemetry export
(app/observability/otel_export.py), a PII redaction mode (PII_MODE=redact
actually masks detected PII before chunking/embedding, not just a warning),
and vision-based OCR for scanned PDFs (app/services/ocr.py) via an OpenAI
vision model. All three are OFF by default and fail open if their optional
dependency isn't installed -- this installer does not install any of
requirements-otel.txt / requirements-ocr.txt / requirements-hnsw.txt by
default, since none of them are needed unless you opt in.

Run this from inside your existing production-rag project folder:

    python apply_day21.py

What it does:
  1. Extracts this script's embedded project snapshot to a temp directory.
  2. Compares every file against what's already in this folder. New or
     changed files are installed; unchanged files are left alone. Anything
     that gets replaced is backed up first to _backup_before_day21/.
  3. NEVER touches: .env, .venv/, app/storage/, evals/reports/,
     evals/golden/, or any earlier _backup_before_dayN/ folder.
  4. Installs requirements-dev.txt (use --prod-only for requirements.txt
     instead, if you don't need to run tests).
  5. Runs scripts/verify_day21.py --offline (use --no-verify to skip;
     --no-install to skip the pip step too, e.g. if you're offline).

To actually USE today's features (all optional, all off by default):
  PII_MODE=redact            in .env -- no extra install needed
  OCR_ENABLED=true           in .env, then: pip install -r requirements-ocr.txt
  OTEL_ENABLED=true          in .env, then: pip install -r requirements-otel.txt
"""
import argparse
import base64
import filecmp
import io
import shutil
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

PROTECTED_PREFIXES = (".env", ".venv", "app/storage", "evals/reports", "evals/golden")

PAYLOAD = """"""


def is_protected(rel_path: str) -> bool:
    if rel_path.startswith("_backup_before_day"):
        return True
    for prefix in PROTECTED_PREFIXES:
        if rel_path == prefix or rel_path.startswith(prefix + "/") or rel_path.startswith(prefix + "\\"):
            return True
    return False


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--no-install", action="store_true", help="skip pip install")
    ap.add_argument("--prod-only", action="store_true",
                     help="install requirements.txt instead of requirements-dev.txt (no pytest/httpx/fpdf2)")
    ap.add_argument("--no-verify", action="store_true", help="skip running scripts/verify_day21.py")
    args = ap.parse_args()

    dest = Path.cwd()
    backup_dir = dest / "_backup_before_day21"

    raw = base64.b64decode(PAYLOAD)
    with tempfile.TemporaryDirectory() as tmp:
        tmp_path = Path(tmp)
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            zf.extractall(tmp_path)

        new_count = replaced_count = unchanged_count = 0
        for src_file in sorted(tmp_path.rglob("*")):
            if src_file.is_dir():
                continue
            rel = src_file.relative_to(tmp_path)
            rel_str = rel.as_posix()
            if is_protected(rel_str):
                continue
            dst_file = dest / rel

            if not dst_file.exists():
                dst_file.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src_file, dst_file)
                new_count += 1
                continue

            if filecmp.cmp(src_file, dst_file, shallow=False):
                unchanged_count += 1
                continue

            backup_path = backup_dir / rel
            backup_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(dst_file, backup_path)
            shutil.copy2(src_file, dst_file)
            replaced_count += 1

    print(f"Day 21 applied: {new_count} new, {replaced_count} replaced (backed up), "
          f"{unchanged_count} unchanged.")
    print("Untouched: .env, .venv, app/storage, evals/reports, evals/golden")
    if replaced_count:
        print(f"Old versions saved in: {backup_dir}")

    if not args.no_install:
        req_file = "requirements.txt" if args.prod_only else "requirements-dev.txt"
        print(f"\nInstalling {req_file}...")
        subprocess.run([sys.executable, "-m", "pip", "install", "-r", req_file], check=False)
        print("(Not installed: requirements-hnsw.txt / requirements-ocr.txt / requirements-otel.txt -- "
              "each is only needed if you opt into that feature; see README.md.)")

    if not args.no_verify:
        print("\nRunning verification...\n")
        subprocess.run([sys.executable, "scripts/verify_day21.py", "--offline"], check=False)
    else:
        print("\nSkipped verification (--no-verify). Run manually with:")
        print("  python scripts/verify_day21.py --offline")

    return 0


if __name__ == "__main__":
    sys.exit(main())
